0a86\u0ab2\u0acd\u0a95\u0ab2\u0abe\u0a87\u0aa8 + \u0aae\u0abf\u0aa8\u0ab0\u0ab2\u0acd\u0ab8", "\u0a95\u0ac7\u0aac\u0abf\u0aa8\u0ac7\u0a9f \u0aae\u0a9f\u0ac0\u0ab0\u0ac0\u0aaf\u0ab2": "\u0aac\u0acd\u0ab0\u0ab6\u0acd\u0aa1 \u0aab\u0abf\u0aa8\u0abf\u0ab6 \u0aaa\u0acd\u0ab0\u0ac0\u0aae\u0abf\u0aaf\u0aae ABS", "\u0a87\u0aa8\u0acd\u0ab8\u0acd\u0a9f\u0acb\u0ab2\u0ac7\u0ab6\u0aa8 \u0aaa\u0acd\u0ab0\u0a95\u0abe\u0ab0": "\u0ab5\u0acb\u0ab2 \u0aae\u0abe\u0a89\u0aa8\u0acd\u0a9f\u0ac7\u0aa1", "\u0ab5\u0acb\u0ab0\u0a82\u0a9f\u0ac0": "\u0ae7 \u0ab5\u0ab0\u0acd\u0ab7"}','LX Series Titanium - Shivam Aqua Solution Morbi','Buy LX Series Titanium RO water purifier in Morbi & Rajkot. Timeless Luxury in Gun Metal & Alpine Gold. Sales, installation, and repair services by Shivam Aqua Solution.',17);